import { useMemo, useState } from 'react';
import { JxStepper, JxInputField, JxButton } from '@jinx-ui/react';

type ContactData = {
  name: string;
  email: string;
  phone: string;
};

type AddressData = {
  country: string;
  city: string;
  street: string;
};

export type RegistrationData = {
  contact: ContactData;
  address: AddressData;
};

type RegistrationFormProps = {
  onSubmit: (data: RegistrationData) => void;
};

const STEPS = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

export default function RegistrationForm({ onSubmit }: RegistrationFormProps) {
  const [step, setStep] = useState(0);
  const [contact, setContact] = useState<ContactData>({ name: '', email: '', phone: '' });
  const [address, setAddress] = useState<AddressData>({ country: '', city: '', street: '' });

  const emailError = contact.email.length > 0 && !contact.email.includes('@') ? 'Укажите адрес с символом @' : undefined;

  const canGoNext = useMemo(() => {
    if (step === 0) {
      return contact.name.trim().length > 0 && contact.email.trim().length > 0 && !emailError;
    }
    if (step === 1) {
      return address.country.trim().length > 0 && address.city.trim().length > 0 && address.street.trim().length > 0;
    }
    return true;
  }, [step, contact, address, emailError]);

  const isLast = step === STEPS.length - 1;

  const goBack = () => setStep((current) => Math.max(current - 1, 0));
  const goNext = () => setStep((current) => Math.min(current + 1, STEPS.length - 1));

  const handleSubmit = () => {
    onSubmit({ contact, address });
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 24, maxWidth: 480 }}>
      <JxStepper steps={STEPS} current={step} />

      <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
        {step === 0 && (
          <>
            <JxInputField
              label="Имя"
              required
              value={contact.name}
              onChange={(event) => setContact({ ...contact, name: event.target.value })}
            />
            <JxInputField
              label="Электронная почта"
              type="email"
              required
              value={contact.email}
              onChange={(event) => setContact({ ...contact, email: event.target.value })}
              errorText={emailError}
            />
            <JxInputField
              label="Телефон"
              type="tel"
              prefix="+7"
              value={contact.phone}
              onChange={(event) => setContact({ ...contact, phone: event.target.value })}
            />
          </>
        )}

        {step === 1 && (
          <>
            <JxInputField
              label="Страна"
              required
              value={address.country}
              onChange={(event) => setAddress({ ...address, country: event.target.value })}
            />
            <JxInputField
              label="Город"
              required
              value={address.city}
              onChange={(event) => setAddress({ ...address, city: event.target.value })}
            />
            <JxInputField
              label="Улица и дом"
              required
              value={address.street}
              onChange={(event) => setAddress({ ...address, street: event.target.value })}
            />
          </>
        )}

        {step === 2 && (
          <div
            style={{
              display: 'flex',
              flexDirection: 'column',
              gap: 8,
              padding: 16,
              borderRadius: 'var(--jx-r)',
              background: 'var(--jx-surface-2)',
              color: 'var(--jx-text)',
            }}
          >
            <strong>Контакты</strong>
            <span>Имя: {contact.name || '—'}</span>
            <span>Почта: {contact.email || '—'}</span>
            <span>Телефон: {contact.phone || '—'}</span>
            <strong>Адрес</strong>
            <span>Страна: {address.country || '—'}</span>
            <span>Город: {address.city || '—'}</span>
            <span>Улица: {address.street || '—'}</span>
          </div>
        )}
      </div>

      <div style={{ display: 'flex', justifyContent: 'space-between', gap: 12 }}>
        <JxButton variant="ghost" type="button" disabled={step === 0} onClick={goBack}>
          Назад
        </JxButton>
        {isLast ? (
          <JxButton variant="primary" type="button" onClick={handleSubmit}>
            Отправить
          </JxButton>
        ) : (
          <JxButton variant="primary" type="button" disabled={!canGoNext} onClick={goNext}>
            Дальше
          </JxButton>
        )}
      </div>
    </div>
  );
}

